def clean(df):
    df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    df['sex'] = df['sex'].replace('FEMALE', 'female')
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    sex_avg = df.groupby('sex')['body_mass_g'].mean().to_dict()
    all_avg = df['body_mass_g'].mean()
    result = {**sex_avg, 'all': all_avg}
    return {k: round(v, 2) for k, v in result.items()}
